+/**
+ * Switch a coinbase-only block template to a different parent and timestamp.
+ * Rebuild the difficulty, coinbase height, locktime, subsidy and input script, then update the merkle root.
+ */
+void SwitchBlockParent(CBlock& block, const CBlockIndex& parent, uint32_t new_time, const Consensus::Params& params);
+
 /**
  * Build a chain of `length` coinbase-only blocks on top of `pindex` (which need
  * not be the active tip, allowing forks to be created) and submit their headers.
diff --git a/src/test/util/mining.cpp b/src/test/util/mining.cpp
index 614a6b96b0..e0ec886b63 100644
--- a/src/test/util/mining.cpp
+++ b/src/test/util/mining.cpp
@@ -79,6 +79,23 @@ std::vector<std::shared_ptr<CBlock>> CreateBlockChain(size_t total_height, const
     return ret;
 }

+void SwitchBlockParent(CBlock& block, const CBlockIndex& parent, uint32_t new_time, const Consensus::Params& params)
+{
+    // Replacing the reward with the subsidy would discard any transaction fees.
+    Assert(block.vtx.size() == 1);
+    block.hashPrevBlock = parent.GetBlockHash();
+    block.nTime = new_time;
+    block.nBits = GetNextWorkRequired(&parent, &block, params);
+    const int height{parent.nHeight + 1};
+    CMutableTransaction tx_coinbase{*block.vtx.at(0)};
+    tx_coinbase.nLockTime = static_cast<uint32_t>(parent.nHeight);
+    // Include a dummy OP_0 so low-height coinbase input scripts meet the minimum length
+    tx_coinbase.vin.at(0).scriptSig = CScript{} << height << OP_0;
+    tx_coinbase.vout.at(0).nValue = GetBlockSubsidy(height, params);
+    block.vtx.at(0) = MakeTransactionRef(std::move(tx_coinbase));
+    block.hashMerkleRoot = BlockMerkleRoot(block);
+}
